  8	/** As situações do pedido e para onde cada uma pode ir. */
  9	public enum OrderStatus {
 10	    AWAITING_PAYMENT,
 11	    PAID,
 12	    SHIPPED,
 13	    DELIVERED,
 14	    CANCELLED;
 15	
 16	    private static final Map<OrderStatus, Set<OrderStatus>> NEXT = new EnumMap<>(OrderStatus.class);
 17	
 18	    static {
 19	        NEXT.put(AWAITING_PAYMENT, EnumSet.of(PAID, CANCELLED));
 20	        NEXT.put(PAID, EnumSet.of(SHIPPED, CANCELLED));
 21	        NEXT.put(SHIPPED, EnumSet.of(DELIVERED));
 22	        NEXT.put(DELIVERED, EnumSet.noneOf(OrderStatus.class));
 23	        NEXT.put(CANCELLED, EnumSet.noneOf(OrderStatus.class));
 24	    }
 25	
 26	    public boolean canMoveTo(OrderStatus next) {
 27	        return NEXT.get(this).contains(next);
 28	    }
 29	
 30	    /** Se o pagamento deste pedido foi aceito e não foi desfeito (conta como compra feita). */
 31	    public boolean paymentSettled() {
 32	        return this == PAID || this == SHIPPED || this == DELIVERED;
 33	    }
 34	}
