 52	package com.loja.orders.order;
 53	
 54	import java.time.Clock;
 55	import java.time.Duration;
 56	import java.time.Instant;
 57	import java.time.OffsetDateTime;
 58	import java.time.format.DateTimeParseException;
 59	import java.time.temporal.ChronoUnit;
 60	import java.util.List;
 61	import java.util.UUID;
 62	
 63	import org.springframework.stereotype.Service;
 64	import org.springframework.transaction.annotation.Transactional;
 65	import org.springframework.transaction.support.TransactionTemplate;
 66	
 67	import com.loja.orders.catalog.InventoryService;
 68	import com.loja.orders.checkout.CheckoutCalculator;
 69	import com.loja.orders.checkout.CheckoutRequest;
 70	import com.loja.orders.checkout.CheckoutSummary;
 71	import com.loja.orders.common.ApiException;
 72	import com.loja.orders.common.ErrorCode;
 73	import com.loja.orders.customer.CustomerRepository;
 74	
 75	@Service
 76	public class OrderService {
 77	
 78	    /** Pagamento que chega depois disso do registro do pedido não é aceito. */
 79	    private static final Duration PAYMENT_DEADLINE = Duration.ofHours(48);
 80	
 81	    private final CheckoutCalculator calculator;
 82	    private final OrderRepository orders;
 83	    private final CustomerRepository customers;
 84	    private final InventoryService inventory;
 85	    private final List<OrderLifecycleListener> listeners;
 86	    private final TransactionTemplate transaction;
 87	    private final Clock clock;
 88	
 89	    public OrderService(CheckoutCalculator calculator, OrderRepository orders, CustomerRepository customers,
 90	            InventoryService inventory, List<OrderLifecycleListener> listeners, TransactionTemplate transaction,
 91	            Clock clock) {
 92	        this.calculator = calculator;
 93	        this.orders = orders;
 94	        this.customers = customers;
 95	        this.inventory = inventory;
 96	        this.listeners = listeners;
 97	        this.transaction = transaction;
 98	        this.clock = clock;
 99	    }
100	
101	    public Order place(CheckoutRequest request) {
102	        // O cálculo consulta a transportadora: fica fora da transação para não segurar o banco.
103	        CheckoutSummary summary = calculator.calculate(request);
104	        Order order = new Order(
105	                UUID.randomUUID().toString(),
106	                request.cpf(),
107	                request.email(),
108	                OrderStatus.AWAITING_PAYMENT,
109	                Instant.now(clock).truncatedTo(ChronoUnit.SECONDS),
110	                summary,
111	                request.items(),
112	                null);
113	        transaction.executeWithoutResult(status -> {
114	            customers.createIfAbsent(order.cpf());
115	            orders.insert(order);
116	        });
117	        return order;
118	    }
119	
120	    @Transactional(readOnly = true)
121	    public Order get(String id) {
122	        return orders.findById(id).orElseThrow(OrderService::notFound);
123	    }
124	
125	    @Transactional(noRollbackFor = PaymentRejectedException.class)
126	    public Order registerPayment(String id, String transactionId, String paidAtText) {
127	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
128	        Instant paidAt = parseInstant(paidAtText);
129	        if (transactionId == null || paidAt == null) {
130	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
131	        }
132	        var previousNotice = orders.findPaymentNotice(id, transactionId);
133	        if (previousNotice.isPresent()) {
134	            return repeat(order, previousNotice.get());
135	        }
136	        requireTransition(order, OrderStatus.PAID);
137	
138	        if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_DEADLINE) > 0) {
139	            return reject(order, transactionId, PaymentNoticeOutcome.ORDER_EXPIRED);
140	        }
141	        if (!inventory.take(order.items())) {
142	            return reject(order, transactionId, PaymentNoticeOutcome.INSUFFICIENT_STOCK);
143	        }
144	        orders.markPaid(id, transactionId, paidAt);
145	        orders.savePaymentNotice(id, transactionId, PaymentNoticeOutcome.ACCEPTED);
146	        Order paid = reload(id);
147	        listeners.forEach(listener -> listener.paymentApproved(paid));
148	        return paid;
149	    }
150	
151	    @Transactional
152	    public Order ship(String id, String trackingCode) {
153	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
154	        if (trackingCode == null) {
155	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
156	        }
157	        requireTransition(order, OrderStatus.SHIPPED);
158	        orders.markShipped(id, trackingCode);
159	        Order shipped = reload(id);
160	        listeners.forEach(listener -> listener.shipped(shipped));
161	        return shipped;
162	    }
163	
164	    @Transactional
165	    public Order deliver(String id) {
166	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
167	        requireTransition(order, OrderStatus.DELIVERED);
168	        orders.updateStatus(id, OrderStatus.DELIVERED);
169	        return reload(id);
170	    }
171	
172	    @Transactional
173	    public Order cancel(String id) {
174	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
175	        requireTransition(order, OrderStatus.CANCELLED);
176	        return cancelLocked(order);
177	    }
178	
179	    private Order repeat(Order order, PaymentNoticeOutcome outcome) {
180	        return switch (outcome) {
181	            case ACCEPTED -> order;
182	            case ORDER_EXPIRED -> throw new PaymentRejectedException(ErrorCode.ORDER_EXPIRED);
183	            case INSUFFICIENT_STOCK -> throw new PaymentRejectedException(ErrorCode.INSUFFICIENT_STOCK);
184	        };
185	    }
186	
187	    private Order reject(Order order, String transactionId, PaymentNoticeOutcome outcome) {
188	        orders.savePaymentNotice(order.id(), transactionId, outcome);
189	        cancelLocked(order);
190	        return repeat(order, outcome);
191	    }
192	
193	    private Order cancelLocked(Order order) {
194	        orders.updateStatus(order.id(), OrderStatus.CANCELLED);
195	        Order cancelled = reload(order.id());
196	        listeners.forEach(listener -> listener.cancelled(cancelled, order.status()));
197	        return cancelled;
198	    }
199	
200	    private Order reload(String id) {
201	        return orders.findById(id).orElseThrow(OrderService::notFound);
202	    }
203	
204	    private static void requireTransition(Order order, OrderStatus next) {
205	        if (!order.status().canMoveTo(next)) {
206	            throw ApiException.conflict(ErrorCode.OPERATION_NOT_ALLOWED);
207	        }
208	    }
209	
210	    private static Instant parseInstant(String text) {
211	        if (text == null) {
212	            return null;
213	        }
214	        try {
215	            return OffsetDateTime.parse(text).toInstant();
216	        } catch (DateTimeParseException e) {
217	            return null;
218	        }
219	    }
220	
221	    private static ApiException notFound() {
222	        return ApiException.notFound(ErrorCode.ORDER_NOT_FOUND);
223	    }
224	}

