  1	package com.loja.orders.order;
  2	
  3	/**
  4	 * O que mais precisa acontecer quando um pedido muda de situação (estoque, crédito do clube, avisos
  5	 * ao cliente...). Para uma reação nova, como SMS ou cashback, basta um novo {@code @Component} que
  6	 * implemente esta interface. Roda na mesma transação da mudança de situação.
  7	 */
  8	public interface OrderLifecycleListener {
  9	
 10	    default void paymentApproved(Order order) {
 11	    }
 12	
 13	    default void shipped(Order order) {
 14	    }
 15	
 16	    default void cancelled(Order order, OrderStatus previousStatus) {
 17	    }
 18	}
