 27	package com.loja.orders.order;
 28	
 29	import org.springframework.http.HttpStatus;
 30	
 31	import com.loja.orders.common.ApiException;
 32	import com.loja.orders.common.ErrorCode;
 33	
 34	/** Pagamento recusado que cancela o pedido: o cancelamento fica gravado mesmo com a recusa. */
 35	public class PaymentRejectedException extends ApiException {
 36	
 37	    public PaymentRejectedException(ErrorCode code) {
 38	        super(HttpStatus.CONFLICT, code);
 39	    }
 40	}
