 63	package com.loja.orders.order;
 64	
 65	import org.springframework.http.HttpStatus;
 66	import org.springframework.web.bind.annotation.GetMapping;
 67	import org.springframework.web.bind.annotation.PathVariable;
 68	import org.springframework.web.bind.annotation.PostMapping;
 69	import org.springframework.web.bind.annotation.RequestBody;
 70	import org.springframework.web.bind.annotation.ResponseStatus;
 71	import org.springframework.web.bind.annotation.RestController;
 72	
 73	import com.loja.orders.checkout.CheckoutRequestParser;
 74	import com.loja.orders.common.JsonBodies;
 75	
 76	import tools.jackson.databind.JsonNode;
 77	
 78	@RestController
 79	public class OrderController {
 80	
 81	    private final CheckoutRequestParser parser;
 82	    private final OrderService service;
 83	    private final JsonBodies bodies;
 84	
 85	    public OrderController(CheckoutRequestParser parser, OrderService service, JsonBodies bodies) {
 86	        this.parser = parser;
 87	        this.service = service;
 88	        this.bodies = bodies;
 89	    }
 90	
 91	    @PostMapping("/orders")
 92	    @ResponseStatus(HttpStatus.CREATED)
 93	    public OrderResponse place(@RequestBody(required = false) String body) {
 94	        return OrderResponse.of(service.place(parser.parse(body)));
 95	    }
 96	
 97	    @GetMapping("/orders/{id}")
 98	    public OrderResponse get(@PathVariable String id) {
 99	        return OrderResponse.of(service.get(id));
100	    }
101	
102	    @PostMapping("/orders/{id}/payment")
103	    public OrderResponse pay(@PathVariable String id, @RequestBody(required = false) String body) {
104	        JsonNode json = bodies.read(body);
105	        return OrderResponse.of(service.registerPayment(id,
106	                JsonBodies.text(json, "transactionId"), JsonBodies.text(json, "paidAt")));
107	    }
108	
109	    @PostMapping("/orders/{id}/shipment")
110	    public OrderResponse ship(@PathVariable String id, @RequestBody(required = false) String body) {
111	        return OrderResponse.of(service.ship(id, JsonBodies.text(bodies.read(body), "trackingCode")));
112	    }
113	
114	    @PostMapping("/orders/{id}/delivery")
115	    public OrderResponse deliver(@PathVariable String id) {
116	        return OrderResponse.of(service.deliver(id));
117	    }
118	
119	    @PostMapping("/orders/{id}/cancellation")
120	    public OrderResponse cancel(@PathVariable String id) {
121	        return OrderResponse.of(service.cancel(id));
122	    }
123	}

